    if(!root)return;controller=new AbortController();const signal=controller.signal;
    const state=()=>getState(),on=(type,handler)=>root.addEventListener(type,handler,{signal});
    const termMap=new Map(glossary.terms.map(term=>[term.id,term]));
    function sourceFootnotes(ids,notes=''){return `<section class="source-footnotes study-sources"><h2>Sources</h2>${notes}<ol>${[...new Set(ids)].filter(id=>sources.has(id)).map(id=>{const source=sources.get(id);return `<li id="study-source-${esc(id)}" data-scripture-source="${esc(id)}" tabindex="-1">${external(source.url,source.title)}${source.attribution?`<p class="required-attribution">${esc(source.attribution)}</p>`:''}<details class="publication-details"><summary>Publication details</summary><p class="reading-attribution">${esc(meta(source))}</p><div class="rights-metadata">${source.rightsUrl?external(source.rightsUrl,source.rights||'Rights'):esc(source.rights||'')}${source.rightsNote?`<p>${esc(source.rightsNote)}</p>`:''}${source.localLicensePath==='licenses/project-gutenberg.txt'?'<p><a href="licenses/project-gutenberg.txt" download>Download source license</a></p>':''}</div>${window.OrthodoxEditorial.sourceContext(id)}</details></li>`;}).join('')}</ol></section>`;}
