      const ids=[prayer.sourceId,...prayer.blocks.map(b=>b.sourceId||prayer.sourceId)],favorite=()=>state().prayerFavorites.includes(prayer.id);
      const prayerWords=norm([prayer.title,...prayer.blocks.map(b=>b.text)].join(' '));
      const terms=glossary.terms.filter(term=>[term.term,...(term.aliases||[])].filter(word=>word.length>=3).some(word=>new RegExp('(^|[^\\p{L}\\p{N}])'+norm(word).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^\\p{L}\\p{N}])','u').test(prayerWords)));
