      if(guided){root.querySelector('.reader-header').insertAdjacentHTML('afterend',`<section class="prayer-guide" aria-labelledby="prayer-guide-title"><h2 id="prayer-guide-title" class="sr-only">Prayer guide</h2><div class="prayer-guide-status"><strong id="prayer-guide-step"></strong><span id="prayer-guide-section"></span></div><div class="prayer-guide-actions"><button class="secondary" id="prayer-guide-prev" type="button">Previous section</button><button class="secondary" id="prayer-guide-next" type="button">Next section</button><a href="#/prayer/${esc(prayer.id)}">Read without guide</a></div></section>`);const updateGuide=()=>{const start=guideSteps[guideIndex],end=guideSteps[guideIndex+1]??prayer.blocks.length,block=prayer.blocks[start],title=block.title||(block.kind==='heading'?block.text:'Opening section');root.querySelector('#prayer-guide-step').textContent='Section '+(guideIndex+1)+' of '+guideSteps.length;root.querySelector('#prayer-guide-section').textContent=title;root.querySelector('#prayer-guide-prev').disabled=guideIndex===0;root.querySelector('#prayer-guide-next').disabled=guideIndex===guideSteps.length-1;root.querySelectorAll('.native-prayer-block').forEach((el,i)=>el.classList.toggle('guide-current',i>=start&&i<end));};on('click',event=>{const button=event.target.closest('#prayer-guide-prev,#prayer-guide-next');if(!button)return;guideIndex+=button.id==='prayer-guide-next'?1:-1;guideIndex=Math.max(0,Math.min(guideSteps.length-1,guideIndex));updateGuide();const target=root.querySelector(`[data-prayer-block="${guideSteps[guideIndex]}"]`);target.tabIndex=-1;window.GlossaryPreviews?.close();target.scrollIntoView({behavior:'smooth',block:'center'});target.focus({preventScroll:true});});updateGuide();}
      let hidden=false,visibleY=state().prayerReadingScroll[prayer.id]||0;const storePosition=()=>{if(hidden)return;visibleY=Math.round(window.scrollY);state().prayerReadingScroll[prayer.id]=visibleY;save();};let timer;
      leave=()=>{clearTimeout(timer);if(hidden){state().prayerReadingScroll[prayer.id]=visibleY;save();}else storePosition();};restore=()=>window.scrollTo(0,state().prayerReadingScroll[prayer.id]||0);
